import{B as e,Q as t,s as n,z as r}from"./chunks/framework.GF8LbaeE.js";var i=JSON.parse(`{"title":"Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tutorial.md","filePath":"guide/tutorial.md"}`),a={name:`guide/tutorial.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h1><p>Welcome to the Tutorial guide. This documentation is automatically generated from the latest game features.</p><h2 id="global-tutorial-—-step-4" tabindex="-1">Global Tutorial — Step 4 <a class="header-anchor" href="#global-tutorial-—-step-4" aria-label="Permalink to &quot;Global Tutorial — Step 4&quot;">​</a></h2><p>Step 4 asks the player to run their show by adjudicating its segments.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-global-step4.png" alt="Global Tutorial — Step 4"></p><hr><h2 id="global-tutorial-—-step-1" tabindex="-1">Global Tutorial — Step 1 <a class="header-anchor" href="#global-tutorial-—-step-1" aria-label="Permalink to &quot;Global Tutorial — Step 1&quot;">​</a></h2><p>The tutorial guides new players through the key actions for their mode. Step 1 asks the player to pick their featured wrestler.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-global-step1.png" alt="Global Tutorial — Step 1"></p><hr><h2 id="global-tutorial-—-step-3" tabindex="-1">Global Tutorial — Step 3 <a class="header-anchor" href="#global-tutorial-—-step-3" aria-label="Permalink to &quot;Global Tutorial — Step 3&quot;">​</a></h2><p>Step 3 asks the player to plan their card by adding at least one segment to their show.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-global-step3.png" alt="Global Tutorial — Step 3"></p><hr><h2 id="global-tutorial-—-step-5" tabindex="-1">Global Tutorial — Step 5 <a class="header-anchor" href="#global-tutorial-—-step-5" aria-label="Permalink to &quot;Global Tutorial — Step 5&quot;">​</a></h2><p>Step 5 introduces AI narration — players can configure an AI provider to generate match commentary.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-global-step5.png" alt="Global Tutorial — Step 5"></p><hr><h2 id="global-tutorial-—-step-2" tabindex="-1">Global Tutorial — Step 2 <a class="header-anchor" href="#global-tutorial-—-step-2" aria-label="Permalink to &quot;Global Tutorial — Step 2&quot;">​</a></h2><p>Step 2 guides the player to create their first show in the universe.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-global-step2.png" alt="Global Tutorial — Step 2"></p><hr><h2 id="league-tutorial-—-step-1" tabindex="-1">League Tutorial — Step 1 <a class="header-anchor" href="#league-tutorial-—-step-1" aria-label="Permalink to &quot;League Tutorial — Step 1&quot;">​</a></h2><p>The league tutorial begins by creating a tutorial league and making the player the commissioner. Step 1 shows the Leagues page with the player&#39;s tutorial league.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-league-step1.png" alt="League Tutorial — Step 1"></p><hr><h2 id="league-tutorial-—-step-2" tabindex="-1">League Tutorial — Step 2 <a class="header-anchor" href="#league-tutorial-—-step-2" aria-label="Permalink to &quot;League Tutorial — Step 2&quot;">​</a></h2><p>Step 2 guides the commissioner to invite other players to their league by generating an invite link.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-league-step2.png" alt="League Tutorial — Step 2"></p><hr><h2 id="league-tutorial-—-step-3" tabindex="-1">League Tutorial — Step 3 <a class="header-anchor" href="#league-tutorial-—-step-3" aria-label="Permalink to &quot;League Tutorial — Step 3&quot;">​</a></h2><p>Step 3 instructs the commissioner to start the snake draft once all players have joined.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-league-step3.png" alt="League Tutorial — Step 3"></p><hr><h2 id="league-tutorial-—-step-4" tabindex="-1">League Tutorial — Step 4 <a class="header-anchor" href="#league-tutorial-—-step-4" aria-label="Permalink to &quot;League Tutorial — Step 4&quot;">​</a></h2><p>Step 4 takes the player to the Draft page to make their first wrestler pick, completing the league setup tutorial.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-league-step4.png" alt="League Tutorial — Step 4"></p><hr><h2 id="campaign-tutorial-—-step-1" tabindex="-1">Campaign Tutorial — Step 1 <a class="header-anchor" href="#campaign-tutorial-—-step-1" aria-label="Permalink to &quot;Campaign Tutorial — Step 1&quot;">​</a></h2><p>The campaign tutorial starts by asking the player to assign a wrestler on their Player Dashboard. Only wrestlers allowed by the first campaign chapter are shown.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-campaign-step1.png" alt="Campaign Tutorial — Step 1"></p><hr><h2 id="campaign-tutorial-—-step-2" tabindex="-1">Campaign Tutorial — Step 2 <a class="header-anchor" href="#campaign-tutorial-—-step-2" aria-label="Permalink to &quot;Campaign Tutorial — Step 2&quot;">​</a></h2><p>Step 2 directs the player to the Campaign view where an active campaign has been automatically created for their chosen wrestler.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-campaign-step2.png" alt="Campaign Tutorial — Step 2"></p><hr><h2 id="campaign-tutorial-—-step-3" tabindex="-1">Campaign Tutorial — Step 3 <a class="header-anchor" href="#campaign-tutorial-—-step-3" aria-label="Permalink to &quot;Campaign Tutorial — Step 3&quot;">​</a></h2><p>Step 3 sends the player to the Backstage Actions page to make their first story-driven choice, completing the campaign tutorial.</p><p><img src="/all-time-wrestling-rpg/screenshots/tutorial-campaign-step3.png" alt="Campaign Tutorial — Step 3"></p><hr><h2 id="video-walkthroughs" tabindex="-1">Video Walkthroughs <a class="header-anchor" href="#video-walkthroughs" aria-label="Permalink to &quot;Video Walkthroughs&quot;">​</a></h2><h3 id="campaign-tutorial-walkthrough" tabindex="-1">Campaign Tutorial Walkthrough <a class="header-anchor" href="#campaign-tutorial-walkthrough" aria-label="Permalink to &quot;Campaign Tutorial Walkthrough&quot;">​</a></h3><p>Step 3 — Make Your First Backstage Action</p><video controls width="100%" style="border-radius:8px;margin-bottom:1rem;"><source src="https://javydreamercsw.github.io/all-time-wrestling-rpg/videos/tutorial-campaign-walkthrough.mp4" type="video/mp4"></video><hr><h3 id="league-tutorial-walkthrough" tabindex="-1">League Tutorial Walkthrough <a class="header-anchor" href="#league-tutorial-walkthrough" aria-label="Permalink to &quot;League Tutorial Walkthrough&quot;">​</a></h3><p>Step 4 — Make Your First Draft Pick</p><video controls width="100%" style="border-radius:8px;margin-bottom:1rem;"><source src="https://javydreamercsw.github.io/all-time-wrestling-rpg/videos/tutorial-league-walkthrough.mp4" type="video/mp4"></video><hr><h3 id="global-tutorial-walkthrough" tabindex="-1">Global Tutorial Walkthrough <a class="header-anchor" href="#global-tutorial-walkthrough" aria-label="Permalink to &quot;Global Tutorial Walkthrough&quot;">​</a></h3><p>Step 5 — Enhance with AI</p><video controls width="100%" style="border-radius:8px;margin-bottom:1rem;"><source src="https://javydreamercsw.github.io/all-time-wrestling-rpg/videos/tutorial-global-walkthrough.mp4" type="video/mp4"></video><hr>`,63)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};